using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a default resolver (reflection-based).
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1️⃣  Strongly-typed metadata retrieval: GetTypeInfo<T>()
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind = {personInfo.Kind}, Properties = {personInfo.Properties.Count}");

// 2️⃣  Probe without throwing: TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded → {found!.Type.Name}");
}

// Now try a type the resolver doesn't know about (use an empty resolver).
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty – resolves nothing
};

if (restricted.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
{
    Console.WriteLine("Unexpectedly found metadata!");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) on restricted options → not available (no exception)");
}

public record Person(string Name, int Age);
EOF
dotnet run

